@sig trait QuotationEligibility_Api {
  def id: Art.BridgeId
  def request_facts_Id : Art.PortId
  def order_state_Id : Art.PortId
  def recovery_gate_Id : Art.PortId
  def proposal_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var proposal: Factory_Dispatch_Coordinator.ProposalState.Type = $

  def put_proposal(value : Factory_Dispatch_Coordinator.ProposalState.Type) : Unit = {
    Contract(
      Modifies(proposal),
      Ensures(
        proposal == value
      )
    )
    Spec {
      proposal = value
    }

    Art.putValue(proposal_Id, Factory_Dispatch_Coordinator.ProposalState_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

